with filtered as (select id, name, email, country, segment, signup_date, is_active, credit_limit, age, concat_ws('-', city, email) as city_email_key, coalesce(city, 'NONE') as city_clean from customers where segment is not null and name like 'Noa%') select date_trunc('quarter', signup_date) as quarter_start, date_trunc('month', signup_date) as activity_month, stddev_samp(credit_limit) as credit_limit_stddev, bit_and(age) as age_bit_and from filtered group by 1, 2 order by activity_month
